export function renderAspectDiagram(pattern, positions, utcMs) {
  const {ids,name,requiredEdgeIds}=pattern;
  if (!ids?.length || !requiredEdgeIds?.length || !Number.isFinite(utcMs)) throw new RangeError('Invalid aspect diagram input');
  const edges=requiredEdgeIds.map(key=>{
    const [a,b,angle]=key.split(':').map(Number);
    return [ids.indexOf(a),ids.indexOf(b),angle];
  });
  if (edges.some(([a,b,angle])=>a<0||b<0||!Number.isFinite(angle))) throw new RangeError('Invalid aspect edge');
  return diagramSvg({ids,name},positions,utcMs,{patternTypes:[{name,points:ids,edges}]});
}
